import{discoverItemIcons}from'./rom-items.js';
import {uid} from './model.js';
import {authoring,readAuthoring,usedAuthoring} from './authoring-model.js';
import {makeSpriteGroup,DEFAULT_PALETTE,studioData} from './sprite-workbench.js';
import {encodeSprite4bpp,encodeSpritePalette,literalSpriteLZ,decompressSpriteLZ,decodeSprite4bpp,decodeSpritePalette} from './native-sprites.js';
import {compileScript,decodeScriptText} from './script-engine.js';

export function encodedText(text){return compileScript('end\n@value:\n= '+String(text).replace(/(?<!\\)\$/g,'\\$').replace(/\r?\n/g,'\\n')+'$',0,'frlg').bytes.slice(1);}
export function itemBindings(project){const used=usedAuthoring(project).items;return readAuthoring(project).items.filter(i=>i.enabled!==false&&(i.install==='replace'||used.has(i.id)));}
export function itemIssues(i,project,context=null){const out=[];if(!i.name.trim())out.push('Give the item a name.');if(i.name.length>13)out.push('Native item names have at most 13 characters.');if(!Number.isInteger(i.slot)||i.slot<1)out.push('Choose a native item slot.');if(!i.sourceHash)out.push('Bind the item to its original ROM.');if(context&&i.sourceHash!==context.hash)out.push('This item is bound to another ROM.');if(context&&i.slot>=context.profile?.itemCount)out.push('The item slot is outside this ROM.');if(i.spriteGroupId&&!project.spriteStudio?.groups.some(g=>g.id===i.spriteGroupId&&g.views.item))out.push('The item icon sprite group is missing.');return out;}
export function installItems(project,reader,context,output){const ids=new Map(),reports=[];for(const i of itemBindings(project)){
  if(!context?.profile)throw Error('The opened ROM needs a supported native item record layout.');const issues=itemIssues(i,project,context);if(issues.length)throw Error(i.name+': '+issues.join(' '));if([...ids.values()].includes(i.slot))throw Error('Two item designs target native slot '+i.slot+'.');
  const p=context.profile;if(p.itemTable){const t=p.itemTable;if(!t.validIds.includes(i.slot))throw Error('Choose an existing nonempty item slot.');const at=t.base+i.slot*44;if(t.format==='pointer-name'){if(i.install!=='replace')throw Error('This item layout supports replacing existing records.');if(i.holdSourceId||i.pocket)throw Error('Pocket / held effects are not yet mapped for this item layout.');const name=encodedText(i.name);if(name.length>14)throw Error('Use a name up to 13 characters.');output.int(at+20,0x08000000+output.allocate(name,'Item name'));output.int(at,Math.max(0,Math.min(999999,+i.price||0)));if(i.description!==undefined)output.int(at+12,0x08000000+output.allocate(encodedText(i.description),'Item description'));if(i.spriteGroupId){const g=project.spriteStudio.groups.find(g=>g.id===i.spriteGroupId),v=g.views.item;if(v.width!==24||v.height!==24)throw Error('A bag icon must be 24 × 24.');output.int(at+36,0x08000000+output.allocate(literalSpriteLZ(encodeSprite4bpp(v.frames[0],24,24)),'Item icon'));output.int(at+40,0x08000000+output.allocate(literalSpriteLZ(encodeSpritePalette(g.normal)),'Item palette'));}ids.set(i.id,i.slot);reports.push('Item '+i.slot+': '+i.name);continue;}p.items=t.base;if(i.spriteGroupId)p.itemIcons??=discoverItemIcons(reader,t);}const at=p.items+i.slot*44,record=reader.bytes.slice(at,at+44),v=new DataView(record.buffer),name=encodedText(i.name);if(i.install!=='replace'&&!/^\?+$|^unused|^none$|^—$/i.test(context.data.items[i.slot]?.name||''))throw Error(i.name+': choose an unused item record, or explicitly select Replace.');if(name.length>14)throw Error('The encoded item name exceeds its native slot.');record.fill(255,0,14);record.set(name,0);v.setUint16(14,i.slot,true);v.setUint16(16,Math.max(0,Math.min(65535,+i.price||0)),true);
  // Only effects explicitly represented in the item record are copied. Native
  // medicine/TM/berry logic also uses ID-indexed tables and is never guessed.
  if(i.holdSourceId){const source=context.data.items[i.holdSourceId];if(!source)throw Error('The held-effect template is missing.');record[18]=source.holdEffect;record[19]=i.holdParam===undefined?source.holdEffectParam:Math.max(0,Math.min(255,+i.holdParam||0));}
  if(i.pocket)v.setUint8(26,Math.max(1,Math.min(5,+i.pocket)));
  if(i.description!==undefined){const bytes=encodedText(i.description);if(bytes.length>2000)throw Error('Keep an item description within 2,000 encoded bytes.');v.setUint32(20,0x08000000+output.allocate(bytes,'Item description: '+i.name),true);}
  output.write(at,record);
  if(i.spriteGroupId){const group=project.spriteStudio.groups.find(g=>g.id===i.spriteGroupId),view=group.views.item;if(view.width!==24||view.height!==24||view.frames[0].length!==576)throw Error('A native bag icon must be 24 × 24 pixels.');if(!Number.isInteger(p.itemIcons))throw Error('The native bag icon table is not verified.');const art=output.allocate(literalSpriteLZ(encodeSprite4bpp(view.frames[0],24,24)),'Item icon: '+i.name),palette=output.allocate(literalSpriteLZ(encodeSpritePalette(group.normal)),'Item palette: '+i.name);output.int(p.itemIcons+i.slot*8,0x08000000+art);output.int(p.itemIcons+i.slot*8+4,0x08000000+palette);}
  ids.set(i.id,i.slot);reports.push('Item '+i.slot+': '+i.name+' · definition / description'+(i.spriteGroupId?' / artwork':''));
 }return{ids,reports};}
export function itemMaker(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 async function open(){const items=authoring(api.project()).items,used=usedAuthoring(api.project()).items;api.modal('Item maker',`<p>Create an item design and paint its bag icon. Unused new designs stay in the project; only referenced new items and explicit replacements compile.</p><div class="studio-actions"><button id="itemMakerNew" type="button" class="primary">＋ Create item</button><button id="itemMakerNative" type="button">Native item database</button></div>${items.map(i=>`<button type="button" class="studio-record ${itemIssues(i,api.project()).length?'needs-attention':''}" data-item-design="${i.id}"><span><b>${esc(i.name)}</b><small>${i.slot?'Slot '+i.slot:'Unbound draft'} · ${i.install==='replace'?'Replaces an existing item':used.has(i.id)?'Used in game':'Library only'}</small></span><small>Edit</small></button>`).join('')||'<p>No custom item designs yet.</p>'}`,null,'Done');$('#itemMakerNew').onclick=()=>edit();$('#itemMakerNative').onclick=()=>api.game().open('items');document.querySelectorAll('[data-item-design]').forEach(b=>b.onclick=()=>edit(items.find(i=>i.id===b.dataset.itemDesign)));}
 async function edit(old=null,draft=null){const item=draft||structuredClone(old||{id:uid(),name:'New item',description:'',price:0,enabled:true,install:'new',slot:null,holdSourceId:0,pocket:1});let context=null;try{if(api.session())context=await api.game().context();if(context&&!context.profile&&context.scene)context={...context,...context.scene};}catch{}
  const rows=context?.data?.items||[],unused=rows.filter(r=>r.id>0&&/^\?+$|^unused|^none$|^—$/i.test(r.name)),choices=item.install==='new'?unused:rows.filter(r=>r.id>0),group=api.project().spriteStudio?.groups.find(g=>g.id===item.spriteGroupId);
  api.modal('Item · '+item.name,`<label>Name<input id="makerItemName" maxlength="80" value="${esc(item.name)}"></label><label>Description<textarea id="makerItemDescription" maxlength="1800">${esc(item.description||'')}</textarea></label><div class="field-row"><label>Shop price<input id="makerItemPrice" type="number" min="0" max="65535" value="${item.price||0}"></label><label>Bag pocket<select id="makerItemPocket">${[['1','Items'],['2','Key items'],['3','Poké Balls'],['4','TM / HM'],['5','Berries']].map(([id,name])=>`<option value="${id}" ${+item.pocket===+id?'selected':''}>${name}</option>`).join('')}</select></label></div><label>Install mode<select id="makerItemInstall"><option value="new" ${item.install!=='replace'?'selected':''}>New item · use an unused native record</option><option value="replace" ${item.install==='replace'?'selected':''}>Replace an existing native item</option></select></label><label>Native record<select id="makerItemSlot"><option value="">Choose later…</option>${choices.map(r=>`<option value="${r.id}" ${item.slot===r.id?'selected':''}>${r.id} · ${esc(r.name)}</option>`).join('')}</select></label>${!context?.profile?'<p class="studio-status needs-attention">Open a ROM with a supported native item table to bind an item. Drafts and artwork can be created now.</p>':item.install==='new'&&!unused.length?'<p class="studio-status needs-attention">No unused item records were identified. Choose an explicit replacement or keep a design-only item.</p>':''}<label>Held effect<select id="makerItemEffect"><option value="0">Keep selected record’s effect</option>${rows.filter(r=>r.id&&r.holdEffect).map(r=>`<option value="${r.id}" ${+item.holdSourceId===r.id?'selected':''}>${esc(r.name)} · effect ${r.holdEffect}</option>`).join('')}</select></label><label>Held effect strength (0–255; blank keeps template)<input id="makerItemParam" type="number" min="0" max="255" value="${item.holdParam??''}"></label><p class="hint-line">Field/battle use keeps the chosen record’s native logic. A new held item or scripted key item can reuse record-based effects. Creating a new medicine, ball, TM or berry effect needs its additional engine tables; changing the pocket alone does not create that behavior.</p><div class="studio-actions"><button id="makerItemPaint" type="button">${group?'Paint':'Create'} 24 × 24 item icon</button>${context?.profile&&item.slot?'<button id="makerItemSourceIcon" type="button">Start from native icon</button>':''}${old?'<button id="makerItemDuplicate" type="button">Duplicate design</button>':''}</div><label class="check"><input id="makerItemEnabled" type="checkbox" ${item.enabled!==false?'checked':''}>Include when referenced / replacing</label>`,()=>{collect();persist();},'Save item draft');
  if(context?.profile?.itemTable?.format==='pointer-name'){for(const id of ['#makerItemPocket','#makerItemEffect','#makerItemParam'])$('#'+id.slice(1)).disabled=true;}
  function collect(){item.name=$('#makerItemName').value.trim()||'New item';item.description=$('#makerItemDescription').value;item.price=+$('#makerItemPrice').value||0;item.pocket=$('#makerItemPocket').disabled?undefined:+$('#makerItemPocket').value;item.install=$('#makerItemInstall').value;item.slot=$('#makerItemSlot').value?+$('#makerItemSlot').value:null;item.holdSourceId=$('#makerItemEffect').disabled?0:+$('#makerItemEffect').value||0;item.holdParam=$('#makerItemParam').value===''?undefined:+$('#makerItemParam').value;item.enabled=$('#makerItemEnabled').checked;if(context?.profile)item.sourceHash=context.hash;}
  function persist(){api.change(()=>{const rows=authoring(api.project()).items,index=rows.findIndex(i=>i.id===item.id);if(index>=0)rows[index]=structuredClone(item);else rows.push(structuredClone(item));});api.refresh();api.toast('Item design saved. Use it in a scene or choose an explicit replacement.');}
  $('#makerItemInstall').onchange=()=>{collect();item.slot=null;edit(old,item);};$('#makerItemSlot').onchange=()=>{collect();if(item.slot&&!item.description){const r=rows[item.slot];if(r){item.name=r.name;item.price=r.price;item.pocket=r.pocket;try{item.description=decodeScriptText(context.reader.bytes,r.descriptionAddress).text.replace(/\$$/,'');}catch{}}}edit(old,item);};
  function artwork(native=false){collect();let g=api.project().spriteStudio?.groups.find(g=>g.id===item.spriteGroupId);api.change(()=>{if(!g){g=makeSpriteGroup(item.name);g.kind='item';delete g.creature;g.views={item:{width:24,height:24,frames:[Array(576).fill(0)]}};studioData(api.project()).groups.push(g);item.spriteGroupId=g.id;}if(native){const p=context.profile,id=item.slot,reader=context.reader;if(p.itemTable?.format==='classic')p.itemIcons??=discoverItemIcons(reader,p.itemTable);if(p.itemTable?.format!=='pointer-name'&&!Number.isInteger(p.itemIcons))throw Error('The opened ROM’s item icon table could not be identified.');const pixels=reader.ptr(p.itemTable?.format==='pointer-name'?p.itemTable.base+id*44+36:p.itemIcons+id*8),palette=reader.ptr(p.itemTable?.format==='pointer-name'?p.itemTable.base+id*44+40:p.itemIcons+id*8+4);g.views.item.frames[0]=Array.from(decodeSprite4bpp(decompressSpriteLZ(reader.bytes,pixels),24,24));g.normal=decodeSpritePalette(decompressSpriteLZ(reader.bytes,palette));g.shiny=[...g.normal];}});persist();api.sprites().open({kind:'custom',id:g.id,side:'item'});}
  $('#makerItemPaint').onclick=()=>artwork(false);if($('#makerItemSourceIcon'))$('#makerItemSourceIcon').onclick=()=>artwork(true);if($('#makerItemDuplicate'))$('#makerItemDuplicate').onclick=()=>{collect();item.id=uid();item.name+=' copy';item.install='new';item.slot=null;edit(null,item);};
 }
 return{open,edit};
}
